     // replacing the body with `x.clone_address()` (the spec'd trait method) verifies
     // (1 verified, 0 errors).
     #[verus_spec(result =>
         ensures
             result@ == self@.start,
     )]
     pub fn start(&self) -> T {
         self.start.clone_address()
     }

